{
  "entry": "main.js",
  "name": "STARBOX COFFEE",
  "description": "CLIMB. COLLECT. BREW. A miniature cafe platformer with expressive Milo and Mira. Explore distinct cylindrical Espresso and Latte mazes, follow bean routes around the glass, brave optional star detours and outrun rising coffee. Solid wood, slippery ceramic, regenerating biscuits, large two-thumb controls and instant retries. Free play and Perfect Coffee cards.",
  "maxPlayers": 8,
  "credits": [
    {
      "work": "STARBOX V2 baristas and glass-mug cafe cover",
      "by": "Original artwork created with OpenAI image generation for STARBOX COFFEE"
    },
    {
      "work": "Milo explorer animation polish",
      "by": "Original OpenAI-generated sprite art from the supplied character direction; source and frame data preserved"
    },
    {
      "work": "Original cafe architecture, surface textures, gameplay and synthesized sound",
      "by": "Created for STARBOX COFFEE"
    },
    {
      "work": "DejaVu Sans, Serif and Mono rasterised UI lettering",
      "by": "DejaVu font team; Bitstream Vera licence in assets/font-license.txt"
    }
  ],
  "loading": {
    "background": "#1e3932",
    "accent": "#c8a66a",
    "text": "#f2f0e8",
    "cover": "assets/v2/cover-v2.jpg",
    "fit": "cover"
  },
  "ui": "minimized",
  "stick": false
}

import * as THREE from 'three';

/** Crisp pixel sprites share the world's sampled depth, rather than sitting over it. */
export function createBarista(assets, depthTexture) {
  const entries = {};
  for (const id of ['boy', 'girl']) {
    const source = id === 'boy' && assets.primary ? assets.primary : assets;
    const size = source.meta.gameplayAtlasSize || 320;
    const canvas = new OffscreenCanvas(size, size), ctx = canvas.getContext('2d');
    ctx.imageSmoothingEnabled = false; ctx.drawImage(source.bitmap, 0, 0, size, size);
    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.minFilter = texture.magFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;
    entries[id] = {texture, meta:source.meta, character:source.meta.characters[id]};
  }
  const uniforms = {
    atlas:{value:entries.boy.texture}, sceneDepth:{value:depthTexture},
    viewSize:{value:new THREE.Vector2(640,360)}, frameRect:{value:new THREE.Vector4()},
    anchor:{value:new THREE.Vector2(.5,0)}, flip:{value:1},
    texel:{value:new THREE.Vector2(1/320,1/320)}, warmth:{value:0}, bounce:{value:0}
  };
  const material = new THREE.ShaderMaterial({
    uniforms, transparent:true, depthWrite:false, depthTest:false,
    vertexShader:`
      uniform vec4 frameRect;
      uniform vec2 anchor;
      uniform float flip;
      varying vec2 spriteUV;
      varying vec2 localUV;
      void main() {
        localUV=uv;
        spriteUV=frameRect.xy+vec2(flip>0.0?uv.x:1.0-uv.x,uv.y)*frameRect.zw;
        vec3 p=position;
        p.xy+=vec2(0.5)-anchor;
        gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.0);
      }`,
    fragmentShader:`
      uniform sampler2D atlas;
      uniform sampler2D sceneDepth;
      uniform vec2 viewSize;
      uniform vec2 texel;
      uniform float warmth;
      uniform float bounce;
      varying vec2 spriteUV;
      varying vec2 localUV;
      void main() {
        float worldDepth=texture2D(sceneDepth,gl_FragCoord.xy/viewSize).r;
        if(gl_FragCoord.z>worldDepth+0.000015) discard;
        vec4 pixel=texture2D(atlas,spriteUV);
        if(pixel.a<0.16) discard;
        float edge=1.0-min(texture2D(atlas,spriteUV+vec2(texel.x,0.0)).a,
                           texture2D(atlas,spriteUV+vec2(0.0,texel.y)).a);
        // Preserve the native atlas colours while sharing the café's warm light.
        // The former global green bias made pale skin and cream read as olive.
        vec3 color=pixel.rgb*vec3(1.0,0.98,0.94);
        color+=vec3(0.13,0.085,0.025)*edge*(0.25+warmth);
        color+=vec3(0.045,0.025,0.008)*(1.0-localUV.y)*bounce;
        color*=1.0+warmth*0.07;
        gl_FragColor=vec4(color,pixel.a);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`
  });
  const hero=new THREE.Mesh(new THREE.PlaneGeometry(1,1),material);
  hero.name='Depth-tested pixel barista';hero.frustumCulled=false;
  const scene=new THREE.Scene(),root=new THREE.Group();
  root.scale.setScalar(.24);root.position.y=.85;root.add(hero);scene.add(root);
  let runCycle=0;
  function update(sample, options) {
    const {character='boy',time=0,dt=0,camera,facing=1,landLeft=0,width=640,height=360,light=0}=options;
    const entry=entries[character],meta=entry.meta;
    const animations=entry.character.animations||meta.animations;
    const speed=Math.abs(sample.vTheta);
    let action=sample.result?.success?'victory':landLeft>0&&sample.grounded?'land':
      !sample.grounded?(sample.vY>1.5?'jump':sample.vY>-.8&&animations.apex?'apex':'fall'):
      speed>.12?'run':'idle';
    const animation=animations[action];
    if(action==='run')runCycle+=dt*(animation.fps||10)*Math.max(.55,speed/1.2);
    const clock=action==='run'?runCycle:action==='land'?Math.max(0,.18-landLeft)*(animation.fps||10):time*(animation.fps||1);
    const frame=entry.character.frames[animation.frames[Math.floor(clock)%animation.frames.length]];
    const [x,y,w,h]=frame.rect,[iw,ih]=meta.imageSize;
    uniforms.atlas.value=entry.texture;
    uniforms.frameRect.value.set(x/iw,1-(y+h)/ih,w/iw,h/ih);
    uniforms.anchor.value.set(facing<0?1-frame.anchor[0]:frame.anchor[0],1-frame.anchor[1]);
    uniforms.flip.value=facing;
    uniforms.texel.value.set(1/entry.texture.image.width,1/entry.texture.image.height);
    uniforms.viewSize.value.set(width,height);
    uniforms.warmth.value=light;
    uniforms.bounce.value=Math.max(0,1-(sample.y-sample.coffeeY)/5);
    const size=1.62/meta.nominalBodyHeight;
    hero.position.set(Math.sin(sample.theta)*5,sample.y+.018,Math.cos(sample.theta)*5);
    hero.scale.set(w*size,h*size,1);
    hero.rotation.set(0,Math.atan2(camera.position.x-hero.position.x*.24,camera.position.z-hero.position.z*.24),0);
  }
  return {scene,root,hero,update,dispose(){
    hero.geometry.dispose();material.dispose();
    for(const entry of Object.values(entries))entry.texture.dispose();
  }};
}

export function createContactShadow(world) {
  const canvas=new OffscreenCanvas(64,64),ctx=canvas.getContext('2d');
  const gradient=ctx.createRadialGradient(32,32,2,32,32,31);
  gradient.addColorStop(0,'rgba(35,22,12,0.7)');
  gradient.addColorStop(.4,'rgba(35,22,12,0.36)');gradient.addColorStop(1,'rgba(35,22,12,0)');
  ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);
  const texture=new THREE.CanvasTexture(canvas);texture.generateMipmaps=false;
  const material=new THREE.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false,
    polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1});
  const shadow=new THREE.Mesh(new THREE.PlaneGeometry(1,1),material);
  shadow.rotation.x=-Math.PI/2;shadow.renderOrder=2;world.add(shadow);
  return {object:shadow,update(run,visible){
    const floor=run.platforms.filter(p=>!p.collapsed&&p.y<=run.y+.025&&
      Math.abs(Math.atan2(Math.sin(run.theta-p.angle),Math.cos(run.theta-p.angle)))<p.halfWidth+.01)
      .sort((a,b)=>b.y-a.y)[0];
    const gap=floor?run.y-floor.y:10;
    shadow.visible=Boolean(visible&&floor&&gap<3);
    if(!shadow.visible)return;
    shadow.position.set(Math.sin(run.theta)*5,floor.y+.018,Math.cos(run.theta)*5);
    shadow.scale.set(.90+gap*.17,.62+gap*.13,1);
    material.opacity=Math.max(.08,.72-gap*.18);
  },dispose(){world.remove(shadow);shadow.geometry.dispose();material.dispose();texture.dispose();}};
}

import * as THREE from 'three';
const UP=new THREE.Vector3(0,1,0);
function windowUniform(material) {
  const direction={value:new THREE.Vector3(-.52,.78,.35).normalize()};
  material.userData.setWindowAngle=angle=>direction.value.set(-.52,.78,.35).normalize().applyAxisAngle(UP,angle);
  return direction;
}

// A single inexpensive material supplies coherent window light, enamel highlights
// and the local lantern falloff. It needs no scene lights or extra shadow pass.
export function createCafeMaterial(atlas, {distant = false, luminous = false, polished = false} = {}) {
  const lamps = {value: Array.from({length:16}, () => new THREE.Vector4(0, -100, 0, 0))};
  const material = new THREE.MeshBasicMaterial({map:atlas,vertexColors:true,side:THREE.DoubleSide});
  const windowDirection=windowUniform(material);
  material.customProgramCacheKey = () => `starbox-cafe-24-${Boolean(atlas)}-${distant}-${luminous}-${polished}`;
  material.userData.setLanterns = (positions, root) => {
    root.updateWorldMatrix(true,false);
    positions.slice(0,16).forEach((p,i) => {
      const world=root.localToWorld(p.clone());
      lamps.value[i].set(world.x,world.y,world.z,.78);
    });
  };
  material.onBeforeCompile = shader => {
    shader.uniforms.cafeLamps=lamps;
    shader.uniforms.cafeWindowDirection=windowDirection;
    shader.vertexShader = shader.vertexShader.replace('#include <common>', `#include <common>
      uniform vec4 cafeLamps[16];
      varying vec3 cafePosition;
      varying vec3 cafeNormal;
      varying vec2 cafeTileUV;
      varying float cafeLamp;
    `).replace('#include <begin_vertex>', `#include <begin_vertex>
      vec4 cafeLocal=vec4(position,1.0);
      vec3 cafeN=normal;
      #ifdef USE_INSTANCING
        cafeLocal=instanceMatrix*cafeLocal;
        cafeN=mat3(instanceMatrix)*cafeN;
      #endif
      cafePosition=(modelMatrix*cafeLocal).xyz;
      cafeNormal=normalize(mat3(modelMatrix)*cafeN);
      cafeTileUV=uv;
      cafeLamp=0.0;
      ${distant || luminous ? '' : `for(int i=0;i<16;i++) {
        vec3 d=cafePosition-cafeLamps[i].xyz;
        float pool=max(0.0,1.0-dot(d,d)/max(.001,cafeLamps[i].w*cafeLamps[i].w));
        cafeLamp+=pool*pool;
      }`}
    `);
    shader.fragmentShader = shader.fragmentShader.replace('#include <common>', `#include <common>
      varying vec3 cafePosition;
      varying vec3 cafeNormal;
      varying vec2 cafeTileUV;
      varying float cafeLamp;
      uniform vec3 cafeWindowDirection;
    `).replace('#include <color_fragment>', `#include <color_fragment>
      vec3 n=normalize(cafeNormal);
      if(!gl_FrontFacing)n=-n;
      vec3 windowDirection=normalize(cafeWindowDirection);
      float sun=max(0.0,dot(n,windowDirection));
      float sky=smoothstep(-.7,.9,n.y);
      vec3 illumination=vec3(.32,.34,.30)+sky*vec3(.12,.105,.075)+sun*vec3(.64,.51,.35);
      illumination+=min(cafeLamp,1.3)*vec3(.45,.225,.065);
      float tile=${atlas ? 'floor(cafeTileUV.x*4.0)+(3.0-floor(cafeTileUV.y*4.0))*4.0' : '-1.0'};
      vec2 tileUV=fract(cafeTileUV*4.0);
      float ceramic=1.0-step(.2,abs(tile));
      float brass=1.0-step(.2,abs(tile-5.0));
      float timber=1.0-step(.2,abs(tile-1.0));
      // A clear coat catches the same broad window on every white landing.
      vec3 eye=normalize(cameraPosition-cafePosition);
      vec3 halfLight=normalize(eye+windowDirection);
      float reflection=pow(max(0.0,dot(n,halfLight)),48.0);
      float broadReflection=pow(max(0.0,dot(n,halfLight)),7.0);
      diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.91,.91,.84),ceramic*.25);
      float grain=sin(tileUV.y*103.0+sin(tileUV.x*13.0)*.8)*.025;
      grain*=1.0-smoothstep(1.6,4.0,fwidth(tileUV.y*103.0));
      diffuseColor.rgb*=1.0+timber*grain;
      ${luminous ? `diffuseColor.rgb*=vec3(1.0,.84,.57)*.95;` : `
      diffuseColor.rgb*=illumination*${distant ? '.58' : '1.0'};
      diffuseColor.rgb+=(ceramic*.27+brass*.18)*reflection*vec3(1.0,.89,.66);
      diffuseColor.rgb+=ceramic*broadReflection*vec3(.055,.052,.04);
      diffuseColor.rgb+=brass*pow(max(0.0,dot(n,halfLight)),11.0)*vec3(.08,.052,.014);
      ${polished ? 'diffuseColor.rgb+=pow(max(0.0,dot(n,halfLight)),22.0)*vec3(.12,.081,.034);' : ''}
      `}
    `);
    if(atlas)shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>', `
      #ifdef USE_MAP
        // Explicit LOD and a guard for its CEILING mip keep both trilinear
        // samples inside this cell. At level7 each 128px tile is one texel;
        // sampling its centre retains filtered detail without neighbour colours.
        vec2 cafeDx=dFdx(vMapUv)*512.0,cafeDy=dFdy(vMapUv)*512.0;
        float cafeLod=clamp(log2(max(1.0,max(length(cafeDx),length(cafeDy)))),0.0,7.0);
        float cafeGuard=exp2(ceil(cafeLod))/1024.0;
        vec2 cafeCell=floor(vMapUv*4.0)*.25;
        vec2 cafeSampleUV=clamp(vMapUv,cafeCell+vec2(cafeGuard),cafeCell+vec2(.25-cafeGuard));
        diffuseColor*=textureLod(map,cafeSampleUV,cafeLod);
      #endif
    `);
  };
  return material;
}

// Coffee deliberately has no atlas sampler: downsampled neighbouring green tiles
// cannot contaminate the liquid, and its reflections stay warm and restrained.
export function createCoffeeMaterial({volume = false} = {}) {
  const time={value:0};
  const material=new THREE.ShaderMaterial({
    side:THREE.DoubleSide,
    uniforms:{time},
    vertexShader:`
      varying vec3 coffeePoint;
      varying vec3 coffeeWorld;
      void main(){
        coffeePoint=position;
        coffeeWorld=(modelMatrix*vec4(position,1.0)).xyz;
        gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);
      }`,
    fragmentShader:`
      uniform float time;
      uniform vec3 cafeWindowDirection;
      varying vec3 coffeePoint;
      varying vec3 coffeeWorld;
      float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
      float noise(vec2 p){
        vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);
        return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);
      }
      void main(){
        vec2 p=coffeePoint.xz;
        float radius=length(p)/5.94;
        float angle=atan(p.y,p.x);
        float marbling=noise(p*.82+vec2(time*.018,-time*.012));
        float fine=noise(p*4.0+marbling*.7);
        vec3 coffee=mix(vec3(.041,.012,.004),vec3(.135,.047,.012),marbling*.72+fine*.10);
        ${volume ? `
          coffee*=.63+.22*smoothstep(-.5,.5,coffeePoint.y);
          coffee+=vec3(.028,.012,.003)*pow(max(0.0,cos(atan(coffeePoint.z,coffeePoint.x)+1.0)),12.0);
        ` : `
          // Irregular crema gathers at the meniscus, never a flat yellow disk.
          float cream=smoothstep(.77,.985,radius+(marbling-.5)*.16);
          float streak=sin(angle*8.0+radius*25.0+marbling*6.0-time*.08)*.5+.5;
          cream*=.48+.52*noise(p*2.6);
          cream+=smoothstep(.80,.97,streak)*smoothstep(.5,.95,radius)*.12;
          coffee=mix(coffee,vec3(.43,.215,.070),clamp(cream,0.0,.78));
          float ripple=sin(length(p-vec2(-2.2,-1.1))*8.5-time*3.2)*.018;
          vec3 n=normalize(vec3(-.035*sin(p.x*1.4+time),1.0,.03*cos(p.y*1.3-time)+ripple));
          vec3 eye=normalize(cameraPosition-coffeeWorld);
          vec3 reflected=reflect(-eye,n);
          float window=pow(max(0.0,dot(reflected,normalize(cafeWindowDirection))),35.0);
          // Broken window sheen reads as liquid without painting green reflections.
          coffee+=vec3(.24,.16,.065)*window*(.35+fine*.65);
          coffee+=vec3(.016,.009,.003)*pow(1.0-max(0.0,dot(eye,n)),4.0);
        `}
        gl_FragColor=vec4(coffee,1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`
  });
  material.uniforms.cafeWindowDirection=windowUniform(material);
  material.userData.time=time;
  return material;
}

import * as THREE from 'three';
import {RADIUS} from './rules.js';
import {createCafeMaterial} from './cafe-materials.js';

function shade(geometry) {
  const n=geometry.getAttribute('normal'),c=[];
  for(let i=0;i<n.count;i++) {
    // Actual window shading runs after each ingredient's instance rotation, so
    // its highlight agrees with the ceramic ledge and the barista beside it.
    c.push(1,1,1);
  }
  geometry.setAttribute('color',new THREE.Float32BufferAttribute(c,3));
  return geometry;
}
function starGeometry() {
  const shape=new THREE.Shape();
  for(let i=0;i<10;i++) {
    const a=i*Math.PI/5+Math.PI/2,r=i%2?.16:.35,x=Math.cos(a)*r,y=Math.sin(a)*r;
    if(i)shape.lineTo(x,y);else shape.moveTo(x,y);
  }
  shape.closePath();
  const geometry=new THREE.ExtrudeGeometry(shape,{depth:.1,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:1,steps:1});
  geometry.translate(0,0,-.05);return shade(geometry);
}

export function createCollectibles(world,course,assets={}) {
  const root=new THREE.Group();world.add(root);
  const material=createCafeMaterial(null,{polished:true});
  const glowCanvas=new OffscreenCanvas(64,64),ctx=glowCanvas.getContext('2d');
  const gradient=ctx.createRadialGradient(32,32,3,32,32,31);
  gradient.addColorStop(0,'rgba(255,255,255,0.65)');gradient.addColorStop(.5,'rgba(255,255,255,0.14)');
  gradient.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);
  const glowTexture=new THREE.CanvasTexture(glowCanvas);glowTexture.generateMipmaps=false;
  const haloMaterial=new THREE.MeshBasicMaterial({map:glowTexture,color:0xf2cc86,transparent:true,opacity:.24,depthWrite:false});
  const shadowMaterial=new THREE.MeshBasicMaterial({map:glowTexture,color:0x20140d,transparent:true,opacity:.48,depthWrite:false});
  const sphere=shade(new THREE.SphereGeometry(1,16,10));
  const profile=[[0,-.33],[.13,-.29],[.22,-.16],[.23,-.02],[.18,.14],[.08,.32],[0,.47]];
  const drop=shade(new THREE.LatheGeometry(profile.map(p=>new THREE.Vector2(...p)),16));
  const crease=new THREE.CatmullRomCurve3([new THREE.Vector3(-.02,-.23,.145),
    new THREE.Vector3(-.065,-.06,.18),new THREE.Vector3(.045,.08,.18),new THREE.Vector3(.025,.23,.13)]);
  const star=starGeometry(),seam=shade(new THREE.TubeGeometry(crease,12,.022,5,false));
  const haloGeometry=new THREE.PlaneGeometry(1.25,1.25);
  const shadowGeometry=new THREE.PlaneGeometry(.72,.53);shadowGeometry.rotateX(-Math.PI/2);
  const types={bean:[],milk:[],star:[]};
  for(const item of course.ingredients)types[item.kind]?.push(item);
  const batches={},all=[];
  for(const [kind,list] of Object.entries(types)) {
    if(!list.length)continue;
    const geo=kind==='bean'?sphere:kind==='milk'?drop:star;
    const batch=new THREE.InstancedMesh(geo,material,list.length);
    batch.frustumCulled=false;root.add(batch);batches[kind]=batch;
    list.forEach((item,index)=>{
      batch.setColorAt(index,new THREE.Color(kind==='bean'?0x99562f:kind==='milk'?0xfff6df:0xf4b843));
      all.push({...item,index,batch,phase:index*1.7});
    });
  }
  const beans=types.bean;
  const seams=beans.length?new THREE.InstancedMesh(seam,material,beans.length):null;
  if(seams) {
    seams.frustumCulled=false;root.add(seams);
    beans.forEach((_,i)=>seams.setColorAt(i,new THREE.Color(0x40281b)));
  }
  const halos=new THREE.InstancedMesh(haloGeometry,haloMaterial,all.length);
  halos.frustumCulled=false;root.add(halos);
  const shadows=new THREE.InstancedMesh(shadowGeometry,shadowMaterial,all.length);
  shadows.frustumCulled=false;root.add(shadows);
  const highlights=new THREE.InstancedMesh(sphere,material,all.length);
  highlights.frustumCulled=false;root.add(highlights);
  all.forEach((item,i)=>highlights.setColorAt(i,new THREE.Color(item.kind==='bean'?0xe5b17b:0xfff9da)));
  const sparkGeometry=shade(new THREE.BoxGeometry(.08,.08,.08));
  const sparkMaterial=new THREE.MeshBasicMaterial({color:0xffd68a,vertexColors:true});
  const sparks=new THREE.InstancedMesh(sparkGeometry,sparkMaterial,24);
  sparks.frustumCulled=false;root.add(sparks);
  const transform=new THREE.Object3D(),burst=[];
  function collect(id,time) {
    const item=all.find(i=>i.id===id);if(!item)return;
    burst.push({time,x:Math.sin(item.angle)*RADIUS,y:item.y,z:Math.cos(item.angle)*RADIUS});
    if(burst.length>3)burst.shift();
  }
  function update(run,time,{windowAngle=0}={}) {
    material.userData.setWindowAngle(windowAngle);
    const states=new Map(run.ingredients.map(item=>[item.id,item]));
    all.forEach((item,haloIndex)=>{
      const taken=states.get(item.id)?.collected;
      const y=item.y+Math.sin(time*3.3+item.phase)*.065;
      transform.position.set(Math.sin(item.angle)*RADIUS,y,Math.cos(item.angle)*RADIUS);
      transform.rotation.set(0,item.angle+Math.sin(time*1.4+item.phase)*.3,item.kind==='bean'?.35:0);
      if(item.kind==='bean')transform.scale.set(.25,.36,.18);else transform.scale.setScalar(1);
      if(taken)transform.scale.setScalar(0);
      transform.updateMatrix();item.batch.setMatrixAt(item.index,transform.matrix);
      if(item.kind==='bean'&&seams) {
        transform.scale.setScalar(taken?0:1);transform.updateMatrix();seams.setMatrixAt(item.index,transform.matrix);
      }
      // A small cream highlight sits on the dimensional front of every icon.
      const radial=.17;
      transform.position.set(Math.sin(item.angle)*(RADIUS+radial)-Math.cos(item.angle)*.055,y+.12,
        Math.cos(item.angle)*(RADIUS+radial)+Math.sin(item.angle)*.055);
      transform.scale.set(taken?0:.045,taken?0:.082,taken?0:.022);transform.rotation.set(0,item.angle,0);
      transform.updateMatrix();highlights.setMatrixAt(haloIndex,transform.matrix);
      transform.position.set(Math.sin(item.angle)*RADIUS,y,Math.cos(item.angle)*RADIUS);
      if(assets.camera)transform.quaternion.copy(assets.camera.quaternion);
      else transform.rotation.set(0,item.angle,0);
      transform.scale.setScalar(taken?0:1+Math.sin(time*3+item.phase)*.06);transform.updateMatrix();
      halos.setMatrixAt(haloIndex,transform.matrix);
      const platform=run.platforms[item.platform];
      transform.position.y=platform.y+.024;transform.rotation.set(0,0,0);
      transform.scale.setScalar(taken||platform.collapsed?0:1);transform.updateMatrix();
      shadows.setMatrixAt(haloIndex,transform.matrix);
    });
    for(const batch of Object.values(batches))batch.instanceMatrix.needsUpdate=true;
    if(seams)seams.instanceMatrix.needsUpdate=true;
    halos.instanceMatrix.needsUpdate=true;
    highlights.instanceMatrix.needsUpdate=true;shadows.instanceMatrix.needsUpdate=true;
    const last=burst[burst.length-1],age=last?time-last.time:10;
    for(let i=0;i<24;i++) {
      if(age<.6) {
        const a=i*2.39996,speed=.55+(i%5)*.18;
        transform.position.set(last.x+Math.cos(a)*age*speed,last.y+.2+age*(1.8+i%3*.25)-age*age*2.5,last.z+Math.sin(a)*age*speed);
        transform.scale.setScalar((1-age/.6)*(.65+i%3*.22));transform.rotation.set(age*4,a,age*3);
      } else transform.scale.setScalar(0);
      transform.updateMatrix();sparks.setMatrixAt(i,transform.matrix);
    }
    sparks.instanceMatrix.needsUpdate=true;
  }
  return {root,update,collect,dispose(){
    world.remove(root);
    for(const b of [...Object.values(batches),halos,seams,sparks,highlights,shadows])b?.dispose();
    for(const geometry of [sphere,drop,star,seam,haloGeometry,shadowGeometry,sparkGeometry])geometry.dispose();
    material.dispose();haloMaterial.dispose();sparkMaterial.dispose();shadowMaterial.dispose();glowTexture.dispose();
  }};
}

/** Swept body/slab collision in the cup's unwrapped angular/vertical plane.
 * y is always the feet. Rendering depth never participates in gameplay contact.
 */
export const BODY = Object.freeze({halfAngle: .045, height: 1.52});
export const platformThickness = p => p.kind === 'rest' ? .43 : p.kind === 'biscuit' ? .24 : p.kind === 'safe' ? .14 : .28;
const EPS = 1e-8, TAU = Math.PI * 2;

export function overlapsBody(theta, y, p) {
  const angle = p.angle + Math.round((theta - p.angle) / TAU) * TAU;
  return Math.abs(theta - angle) < p.halfWidth + BODY.halfAngle - EPS &&
    y < p.y - EPS && y + BODY.height > p.y - platformThickness(p) + EPS;
}

export function sweepBody(theta, y, dx, dy, platforms) {
  let x = theta, feet = y, landing = null;
  const contacts = [];
  // A contact removes only its normal velocity; the remaining motion slides along it.
  for (let pass = 0; pass < 4 && (Math.abs(dx) > EPS || Math.abs(dy) > EPS); pass++) {
    let hit = null;
    for (const p of platforms) {
      if (p.collapsed) continue;
      const angle = p.angle + Math.round((x - p.angle) / TAU) * TAU;
      const min = [angle - p.halfWidth - BODY.halfAngle, p.y - platformThickness(p) - BODY.height];
      const max = [angle + p.halfWidth + BODY.halfAngle, p.y];
      const origin = [x, feet], delta = [dx, dy];
      let enter = -Infinity, leave = Infinity, axis = -1;
      let misses = false;
      for (let a = 0; a < 2; a++) {
        if (Math.abs(delta[a]) < EPS) {
          // Tangential motion at a boundary must not snag feet on their own pad.
          if (origin[a] <= min[a] + EPS || origin[a] >= max[a] - EPS) { misses = true; break; }
        } else {
          const t1 = (min[a] - origin[a]) / delta[a], t2 = (max[a] - origin[a]) / delta[a];
          const near = Math.min(t1, t2), far = Math.max(t1, t2);
          if (near > enter) { enter = near; axis = a; }
          leave = Math.min(leave, far);
        }
      }
      if (!misses && enter >= -EPS && enter <= 1 && leave > Math.max(0, enter) + EPS &&
          (!hit || enter < hit.t - EPS || Math.abs(enter-hit.t)<EPS && axis===1)) {
        hit = {p, t: Math.max(0, enter), axis, normal: -Math.sign(delta[axis])};
      }
    }
    if (!hit) { x += dx; feet += dy; break; }
    x += dx * hit.t; feet += dy * hit.t;
    dx *= 1 - hit.t; dy *= 1 - hit.t;
    if (hit.axis === 0) dx = 0;
    else { dy = 0; if (hit.normal === 1) landing = hit.p; }
    contacts.push({platform: hit.p.id, axis: hit.axis, normal: hit.normal});
  }
  return {theta: x, y: feet, landing, contacts};
}

import * as THREE from 'three';

/** One inexpensive depth-aware composite. Sprites and UI render afterwards. */
export function createDioramaComposite(target,camera) {
  const uniforms={map:{value:target.texture},depthMap:{value:target.depthTexture},
    texel:{value:new THREE.Vector2()},planes:{value:new THREE.Vector2(camera.near,camera.far)},
    focusDepth:{value:3.5},focusA:{value:new THREE.Vector2(.5,.45)},focusB:{value:new THREE.Vector2(.5,.6)}};
  const material=new THREE.ShaderMaterial({uniforms,depthTest:false,depthWrite:false,toneMapped:false,
    vertexShader:`varying vec2 screenUV;
      void main(){screenUV=uv;gl_Position=vec4(position.xy,0.0,1.0);}`,
    fragmentShader:`
      uniform sampler2D map;
      uniform sampler2D depthMap;
      uniform vec2 texel;
      uniform vec2 planes;
      uniform float focusDepth;
      uniform vec2 focusA;
      uniform vec2 focusB;
      varying vec2 screenUV;
      float focusMask(vec2 center){return 1.0-smoothstep(.82,1.2,length((screenUV-center)/vec2(.27,.19)));}
      void main(){
        vec3 color=texture2D(map,screenUV).rgb;
        float depth=texture2D(depthMap,screenUV).r;
        float distanceToCamera=planes.x*planes.y/(planes.y-depth*(planes.y-planes.x));
        float farScene=smoothstep(focusDepth+1.25,focusDepth+3.3,distanceToCamera);
        float protectedLane=max(focusMask(focusA),focusMask(focusB));
        float tilt=farScene*(1.0-protectedLane)*(.35+.65*smoothstep(.18,.5,abs(screenUV.y-.48)));
        vec2 offset=texel*(1.0+tilt*1.1);
        vec3 soft=(texture2D(map,screenUV+vec2(offset.x,0.)).rgb+
          texture2D(map,screenUV-vec2(offset.x,0.)).rgb+
          texture2D(map,screenUV+vec2(0.,offset.y)).rgb+
          texture2D(map,screenUV-vec2(0.,offset.y)).rgb)*.25;
        color=mix(color,soft,tilt*.62);
        // Highlight-only warm halation: no full-screen blur or extra render pass.
        vec3 halo=max(soft-vec3(.78),vec3(0.0));
        color+=halo*vec3(.065,.045,.022)*(1.0-protectedLane*.65);
        gl_FragColor=vec4(color,1.0);
        #include <colorspace_fragment>
      }`});
  const point=new THREE.Vector3(),viewPoint=new THREE.Vector3();
  function project(p,out) {point.copy(p).project(camera);out.set(point.x*.5+.5,point.y*.5+.5);}
  return {material,update(heroPoint,nextPoint){
    uniforms.texel.value.set(1/target.width,1/target.height);
    uniforms.planes.value.set(camera.near,camera.far);
    camera.updateMatrixWorld();viewPoint.copy(heroPoint).applyMatrix4(camera.matrixWorldInverse);
    uniforms.focusDepth.value=Math.max(camera.near,-viewPoint.z);
    project(heroPoint,uniforms.focusA.value);project(nextPoint,uniforms.focusB.value);
  },dispose(){material.dispose();}};
}

import {platformThickness} from './collision.js';
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import {createCafeMaterial,createCoffeeMaterial} from './cafe-materials.js';

// All surfaces and furniture are original, deliberately small café geometry.
// Gameplay colliders remain in rules.js; every landing surface uses those angles.
const TAU = Math.PI * 2;
const WHITE = 0xffffff;
// The green coaster's solid top is -3.02. At the initial -3.00 coffee height,
// the former ±.067 ripple passed through it and exposed green polygon islands.
const COASTER_TOP=-3.02, LIQUID_CLEARANCE=.012, MAX_RIPPLE=.07;
const C = {
  cream: 0xf2f0e8, green: 0x006241, forest: 0x1e3932,
  gold: 0xc8a66a, brown: 0x6f4e37, amber: 0xffcf7b
};
const TILE = {
  ceramic: 0, wood: 1, biscuit: 2, brick: 3, green: 4, gold: 5,
  awning: 6, edge: 7, coffee: 8, foam: 9, leaf: 10, crack: 11,
  inset: 12, pot: 13, lantern: 14, white: 15
};
const identity = new THREE.Matrix4();

function transform(x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0, sx = 1, sy = 1, sz = 1) {
  return new THREE.Matrix4().compose(
    new THREE.Vector3(x, y, z),
    new THREE.Quaternion().setFromEuler(new THREE.Euler(rx, ry, rz)),
    new THREE.Vector3(sx, sy, sz)
  );
}

function tintGeometry(geometry, tile, color = WHITE, shade = true) {
  const uv = geometry.getAttribute('uv');
  const position = geometry.getAttribute('position');
  const outUV = new Float32Array(position.count * 2);
  const colors = new Float32Array(position.count * 3);
  const base = new THREE.Color(color);
  for (let i = 0; i < position.count; i++) {
    let u = uv ? uv.getX(i) : 0.5;
    let v = uv ? uv.getY(i) : 0.5;
    u = Math.max(0.018, Math.min(0.982, u));
    v = Math.max(0.018, Math.min(0.982, v));
    outUV[i * 2] = ((tile % 4) + u) / 4;
    outUV[i * 2 + 1] = (3 - Math.floor(tile / 4) + v) / 4;
    // Lighting is evaluated after all local rotations in the material. Baking it
    // here made identical ledges face different apparent window directions.
    const amount = 1;
    colors[i * 3] = base.r * amount;
    colors[i * 3 + 1] = base.g * amount;
    colors[i * 3 + 2] = base.b * amount;
  }
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(outUV, 2));
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  return geometry;
}

function prepared(geometry, matrix, tile, color = WHITE, shade = true) {
  geometry.applyMatrix4(matrix || identity);
  return tintGeometry(geometry, tile, color, shade);
}

function combine(parts) {
  if (!parts.length) return new THREE.BufferGeometry();
  const ready = parts.map(part => {
    const geometry = part.index ? part.toNonIndexed() : part;
    if (geometry !== part) part.dispose();
    const count = geometry.getAttribute('position').count;
    if (!geometry.getAttribute('normal')) geometry.computeVertexNormals();
    if (!geometry.getAttribute('uv')) geometry.setAttribute('uv', new THREE.Float32BufferAttribute(new Float32Array(count * 2), 2));
    if (!geometry.getAttribute('color')) {
      const values = new Float32Array(count * 3); values.fill(1);
      geometry.setAttribute('color', new THREE.Float32BufferAttribute(values, 3));
    }
    return geometry;
  });
  const geometry = mergeGeometries(ready, false);
  ready.forEach(part => part.dispose());
  if (!geometry) throw new Error('Café geometry could not be merged');
  return geometry;
}

function addBox(parts, x, y, z, w, h, d, tile, color = WHITE, ry = 0) {
  parts.push(prepared(new THREE.BoxGeometry(w, h, d), transform(x, y, z, 0, ry), tile, color));
}

function addSphere(parts, x, y, z, sx, sy, sz, tile, color = WHITE) {
  parts.push(prepared(new THREE.SphereGeometry(1, 8, 5), transform(x, y, z, 0, 0, 0, sx, sy, sz), tile, color));
}

function addCylinder(parts, x, y, z, top, bottom, height, tile, color = WHITE, segments = 10) {
  parts.push(prepared(new THREE.CylinderGeometry(top, bottom, height, segments), transform(x, y, z), tile, color));
}

function addTube(parts, from, to, radius, tile, color = WHITE, segments = 6) {
  const a = new THREE.Vector3(...from), b = new THREE.Vector3(...to);
  const position = a.clone().add(b).multiplyScalar(0.5);
  const rotation = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.clone().sub(a).normalize());
  const matrix = new THREE.Matrix4().compose(position, rotation, new THREE.Vector3(1, 1, 1));
  parts.push(prepared(new THREE.CylinderGeometry(radius, radius, a.distanceTo(b), segments), matrix, tile, color));
}

function addRing(parts, y, radius, thickness, tile, color = WHITE, segments = 48) {
  const geometry = new THREE.TorusGeometry(radius, thickness, 5, segments);
  parts.push(prepared(geometry, transform(0, y, 0, Math.PI / 2), tile, color));
}

function sectorGeometry(halfWidth, inner, outer, top, bottom, count = 18) {
  const positions = [], uv = [];
  function point(radius, angle, y) {
    return [Math.sin(angle) * radius, y, Math.cos(angle) * radius];
  }
  function face(a, b, c, uva, uvb, uvc) {
    positions.push(...a, ...b, ...c);
    uv.push(...uva, ...uvb, ...uvc);
  }
  for (let i = 0; i < count; i++) {
    const u = i / count, v = (i + 1) / count;
    const a = -halfWidth + u * halfWidth * 2, b = -halfWidth + v * halfWidth * 2;
    face(point(inner, a, top), point(outer, a, top), point(outer, b, top), [u, 0], [u, 1], [v, 1]);
    face(point(inner, a, top), point(outer, b, top), point(inner, b, top), [u, 0], [v, 1], [v, 0]);
    if (bottom === top) continue;
    for (const radius of [inner, outer]) {
      face(point(radius, a, bottom), point(radius, b, top), point(radius, a, top), [u, 0], [v, 1], [u, 1]);
      face(point(radius, a, bottom), point(radius, b, bottom), point(radius, b, top), [u, 0], [v, 0], [v, 1]);
    }
    face(point(inner, a, bottom), point(outer, b, bottom), point(outer, a, bottom), [u, 0], [v, 1], [u, 1]);
    face(point(inner, a, bottom), point(inner, b, bottom), point(outer, b, bottom), [u, 0], [v, 0], [v, 1]);
  }
  if (top !== bottom) {
    for (const angle of [-halfWidth, halfWidth]) {
      face(point(inner, angle, top), point(outer, angle, top), point(outer, angle, bottom), [0, 1], [1, 1], [1, 0]);
      face(point(inner, angle, top), point(outer, angle, bottom), point(inner, angle, bottom), [0, 1], [1, 0], [0, 0]);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geometry.computeVertexNormals();
  return geometry;
}

function bevelledLedge(halfWidth, inner, outer, thickness) {
  const positions=[],uv=[],steps=18,bevel=Math.min(.065,thickness*.25);
  const levels=[{y:0,i:inner+bevel,o:outer-bevel,a:halfWidth-.007},
    {y:-bevel,i:inner,o:outer,a:halfWidth},
    {y:-thickness+bevel,i:inner,o:outer,a:halfWidth},
    {y:-thickness,i:inner+bevel,o:outer-bevel,a:halfWidth-.007}];
  const point=(level,outerSide,t)=>{
    const a=(t*2-1)*level.a,r=outerSide?level.o:level.i;
    return [Math.sin(a)*r,level.y,Math.cos(a)*r];
  };
  function triangle(a,b,c,ua,ub,uc){positions.push(...a,...b,...c);uv.push(...ua,...ub,...uc);}
  function quad(a,b,c,d,u=0,v=1){
    triangle(a,b,c,[u,0],[v,0],[v,1]);triangle(a,c,d,[u,0],[v,1],[u,1]);
  }
  for(let k=0;k<steps;k++) {
    const a=k/steps,b=(k+1)/steps;
    quad(point(levels[0],false,a),point(levels[0],false,b),point(levels[0],true,b),point(levels[0],true,a),a,b);
    const bottom=levels.at(-1);
    quad(point(bottom,false,a),point(bottom,true,a),point(bottom,true,b),point(bottom,false,b),a,b);
    for(let j=0;j<levels.length-1;j++)for(const outside of [false,true])
      quad(point(levels[j],outside,a),point(levels[j+1],outside,a),point(levels[j+1],outside,b),point(levels[j],outside,b),a,b);
  }
  for(const t of [0,1])for(let j=0;j<levels.length-1;j++)
    quad(point(levels[j],false,t),point(levels[j],true,t),point(levels[j+1],true,t),point(levels[j+1],false,t));
  const geometry=new THREE.BufferGeometry();
  geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  geometry.computeVertexNormals();return geometry;
}

function liquidSurface(radius) {
  const positions=[],uv=[],indices=[],segments=48,rings=6;
  for(let j=0;j<=rings;j++)for(let k=0;k<=segments;k++) {
    const a=k/segments*TAU,r=radius*j/rings,x=Math.sin(a)*r,z=Math.cos(a)*r;
    positions.push(x,0,z);uv.push(x/radius*.5+.5,z/radius*.5+.5);
    if(j&&k){const n=j*(segments+1)+k;indices.push(n,n-1,n-segments-2,n,n-segments-2,n-segments-1);}
  }
  const geometry=new THREE.BufferGeometry();
  geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geometry.setIndex(indices);
  geometry.computeVertexNormals();return geometry;
}

function makePlatform(platform) {
  const kind = platform.kind || 'solid';
  const biscuit = kind === 'biscuit';
  const wood = platform.surface === 'wood';
  const pieces = [];
  const baseTile = biscuit ? TILE.biscuit : wood ? TILE.wood : TILE.edge;
  const topTile = biscuit ? TILE.biscuit : wood ? TILE.wood : TILE.ceramic;
  const thickness = platformThickness(platform);
  pieces.push(prepared(bevelledLedge(platform.halfWidth,4.35,5.65,thickness),identity,baseTile,
    biscuit?0xeac17a:wood?0xb88b5e:0x92b3a5));
  pieces.push(prepared(sectorGeometry(platform.halfWidth-.007,4.415,5.585,.003,.003),identity,topTile));
  if (platform.surface === 'ceramic') {
    // Cool glaze lines distinguish sliding surfaces, including precision landings.
    for (const radius of [4.63, 4.77]) pieces.push(prepared(
      sectorGeometry(platform.halfWidth*.7,radius,radius+.019,.008,.008,12),identity,TILE.ceramic,0xd8e4dc));
    // A pale outer glaze roll and a narrower recessed seam give white porcelain
    // its thickness and clear-coat edge instead of a flat cream rectangle.
    pieces.push(prepared(sectorGeometry(platform.halfWidth-.009,5.52,5.59,.014,-.034),identity,TILE.ceramic,0xfff9ec));
  }
  if(wood&&!biscuit) {
    for(const radius of [4.77,5.20])pieces.push(prepared(
      sectorGeometry(platform.halfWidth-.012,radius,radius+.013,.008,.008),identity,TILE.wood,0x60442e));
    // Tiny end-grain pegs are actual recessed-looking brass joinery.
    for(const side of [-1,1])for(const radius of [4.53,5.45]) {
      const a=side*(platform.halfWidth-.05);
      addCylinder(pieces,Math.sin(a)*radius,.012,Math.cos(a)*radius,.028,.028,.015,TILE.gold,0xad8b4d,8);
    }
  }
  if (!biscuit) {
    // A restrained underside bead leaves the landing edge visually clean.
    pieces.push(prepared(sectorGeometry(platform.halfWidth-.004, 5.57, 5.63, -0.08, -0.12), identity, TILE.gold,0xc8a66a));
    pieces.push(prepared(sectorGeometry(platform.halfWidth-.004, 4.35, 4.40, -0.07, -0.21), identity, TILE.green));
    // Small supporting corbels stop the platforms feeling like flat floating rectangles.
    for (const sign of [-1, 1]) {
      const angle = sign * platform.halfWidth * 0.64;
      addTube(pieces, [Math.sin(angle) * 5.55, -thickness+.02, Math.cos(angle) * 5.55],
        [Math.sin(angle) * 6.08, -0.89, Math.cos(angle) * 6.08], 0.065, TILE.wood);
    }
  }
  return combine(pieces);
}

function icon(parts, centerX, centerY, z, size) {
  const vertices = [], uv = [];
  const points = [];
  for (let i = 0; i < 10; i++) {
    const angle = Math.PI / 2 + i * Math.PI / 5;
    const r = (i % 2 ? 0.17 : 0.39) * size;
    points.push([centerX + Math.cos(angle) * r, centerY + Math.sin(angle) * r, z]);
  }
  for (let i = 0; i < 10; i++) {
    vertices.push(centerX, centerY, z, ...points[i], ...points[(i + 1) % 10]);
    uv.push(0.5, 0.5, 0.1, 0.1, 0.9, 0.9);
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geometry.computeVertexNormals();
  parts.push(prepared(geometry, identity, TILE.gold, WHITE, false));
  addBox(parts, centerX, centerY - size * 0.62, z, size * 0.55, size * 0.38, 0.045, TILE.ceramic);
  addTube(parts, [centerX + size * 0.28, centerY - size * 0.50, z],
    [centerX + size * 0.43, centerY - size * 0.57, z], size * 0.045, TILE.gold);
}

function glowTexture() {
  const canvas = new OffscreenCanvas(64, 64);
  const context = canvas.getContext('2d');
  const gradient = context.createRadialGradient(32, 32, 1, 32, 32, 31);
  gradient.addColorStop(0, 'rgba(255,255,255,0.85)');
  gradient.addColorStop(0.2, 'rgba(255,255,255,0.38)');
  gradient.addColorStop(0.6, 'rgba(255,255,255,0.10)');
  gradient.addColorStop(1, 'rgba(255,255,255,0)');
  context.fillStyle = gradient; context.fillRect(0, 0, 64, 64);
  const texture = new THREE.CanvasTexture(canvas);
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  return texture;
}

// A low-cost wall of original painted café windows behind the real 3D mug.
// It supplies warm depth and distant bokeh without lights, shadows or post effects.
function cafeBackdropTexture(blur = 0) {
  const canvas = new OffscreenCanvas(512, 512);
  const ctx = canvas.getContext('2d');
  const wall = ctx.createLinearGradient(0, 0, 0, 512);
  wall.addColorStop(0, '#101b18');
  wall.addColorStop(0.44, '#34281f');
  wall.addColorStop(1, '#191f19');
  ctx.fillStyle = wall; ctx.fillRect(0, 0, 512, 512);
  // Oak wall panels anchor the windows in a recognizable coffeehouse room.
  for (let y = 404; y < 512; y += 27) {
    ctx.fillStyle = y % 2 ? '#563b25' : '#61432a'; ctx.fillRect(0, y, 512, 26);
    ctx.fillStyle = '#84603b'; ctx.fillRect(0, y, 512, 2);
    for (let k = 0; k < 15; k++) {
      const x = (k * 43 + y * 7) % 512;
      ctx.fillStyle = 'rgba(166,118,63,0.12)'; ctx.fillRect(x, y + 7 + k % 10, 29, 1);
    }
  }
  for (let i = 0; i < 3; i++) {
    const x = 16 + i * 170;
    const halo = ctx.createRadialGradient(x + 70, 220, 12, x + 70, 220, 153);
    halo.addColorStop(0, 'rgba(249,181,78,0.08)');
    halo.addColorStop(1, 'rgba(249,181,78,0)');
    ctx.fillStyle = halo; ctx.fillRect(x - 75, 40, 300, 370);
    ctx.fillStyle = '#352b20'; ctx.fillRect(x - 7, 62, 151, 348);
    ctx.fillStyle = '#a27a45'; ctx.fillRect(x - 3, 66, 143, 340);
    const window = ctx.createLinearGradient(x, 0, x + 132, 0);
    window.addColorStop(0, '#4e3825');
    window.addColorStop(0.26, '#725332');
    window.addColorStop(0.55, '#946d3c');
    window.addColorStop(1, '#59422b');
    ctx.fillStyle = window; ctx.fillRect(x + 3, 73, 131, 326);
    // Broad subtle interior silhouettes read as a distant café, not another level.
    ctx.fillStyle = 'rgba(86,56,31,0.25)';
    ctx.fillRect(x + 8, 331, 123, 48);
    ctx.fillRect(x + 19, 313, 14, 19); ctx.fillRect(x + 92, 309, 19, 23);
    ctx.fillStyle = '#4d3924';
    ctx.fillRect(x + 64, 70, 7, 333); ctx.fillRect(x + 1, 205, 134, 7);
    ctx.fillStyle = '#bd975a'; ctx.fillRect(x - 9, 401, 154, 8);
    ctx.fillStyle = '#795835'; ctx.fillRect(x - 9, 409, 154, 7);
    // Framed deep-green lintel and a soft hanging light above each window.
    ctx.fillStyle = '#1d3c2b'; ctx.fillRect(x - 10, 44, 155, 24);
    ctx.fillStyle = '#a77d45'; ctx.fillRect(x - 10, 44, 155, 2);
    ctx.fillStyle = '#312b20'; ctx.fillRect(x + 66, 0, 3, 105);
    const light = ctx.createRadialGradient(x + 68, 107, 1, x + 68, 107, 38);
    light.addColorStop(0, 'rgba(255,224,143,0.70)');
    light.addColorStop(0.24, 'rgba(255,178,63,0.26)');
    light.addColorStop(1, 'rgba(255,178,63,0)');
    ctx.fillStyle = light; ctx.fillRect(x + 28, 67, 80, 80);
    ctx.fillStyle = '#ddad58';ctx.fillRect(x + 56, 100, 25, 7);
    ctx.fillStyle = '#f8d68a';ctx.fillRect(x + 61, 107, 16, 12);
  }
  // Restrained bokeh and greenery keep the distant wall alive and welcoming.
  for (let i = 0; i < 24; i++) {
    const x = (i * 157 + 29) % 512, y = (i * 89 + 34) % 430;
    const r = 2 + i % 4;
    ctx.fillStyle = 'rgba(239,185,96,0.12)';ctx.beginPath();ctx.arc(x, y, r, 0, TAU);ctx.fill();
  }
  for (let i = 0; i < 30; i++) {
    const x = (i * 89 + 11) % 512, y = 18 + (i * 37) % 50;
    ctx.fillStyle = i % 3 ? '#304f31' : '#49613a';
    ctx.beginPath();ctx.ellipse(x, y, 4, 8, i * 0.9, 0, TAU);ctx.fill();
  }
  let output=canvas;
  if(blur) {
    output=new OffscreenCanvas(512,512);const soft=output.getContext('2d');
    soft.filter=`blur(${blur}px)`;soft.drawImage(canvas,-3,-3,518,518);
  }
  const texture = new THREE.CanvasTexture(output);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = THREE.RepeatWrapping; texture.wrapT = THREE.RepeatWrapping;
  texture.minFilter = THREE.LinearFilter;texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = false;
  return texture;
}

function leafGeometry() {
  const positions = [0, 0, 0.035, -0.15, 0.22, 0, -0.11, 0.47, 0, 0, 0.66, 0, 0.14, 0.44, 0, 0.16, 0.20, 0];
  const uv = [0.5, 0, 0.02, 0.30, 0.15, 0.72, 0.5, 1, 0.88, 0.70, 0.98, 0.30];
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geometry.setIndex([0, 1, 2, 0, 2, 3, 0, 3, 4, 0, 4, 5]);
  geometry.computeVertexNormals();
  return tintGeometry(geometry, TILE.leaf, WHITE, false);
}

/**
